package br.com.admeclesial.interfaces.rest.financeiro; import br.com.admeclesial.application.financeiro.*; import br.com.admeclesial.domain.financeiro.ObrigacaoRepasse; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/obrigacoes-repasse") public class ObrigacaoRepasseRestController { final ObrigacaoRepasseApplicationService s; public ObrigacaoRepasseRestController(ObrigacaoRepasseApplicationService s){this.s=s;} @PostMapping public ObrigacaoRepasse criar(@Valid @RequestBody ObrigacaoRepasseRequest r){return s.gerar(r);} @GetMapping public List<ObrigacaoRepasse> listar(){return s.listar();} }